/// <summary>
/// ATL hands back an AtlEntity WRAPPER; .record() is what turns it into a buffer.
/// </summary>
[SysTestMethod, SysTestCheckInTest]
public void testAtlYieldsARealCustomerBuffer()
{
    AtlDataRootNode data = AtlDataRootNode::construct();
    CustTable       customer;

    customer = data.cust().customers().default().record();

    this.assertNotEqual('', customer.AccountNum, 'ATL must hand back a saved customer');
}

/// <summary>
/// The module accessor, not the root, is what a missing package reference breaks.
/// </summary>
[SysTestMethod, SysTestCheckInTest]
public void testAtlItemNodeYieldsAnItem()
{
    AtlDataRootNode data = AtlDataRootNode::construct();
    InventTable     item;

    item = data.invent().items().default();

    this.assertNotEqual('', item.ItemId, 'ATL must hand back a released item');
}
